using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithSeedData();
            _controller = new StudentsController(_context);
            // Set up TempData for controller
            _controller.TempData = new TempDataDictionary(
                new DefaultHttpContext(), 
                new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewResult_WithStudents()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.True(model.Count > 0);
        }

        [Fact]
        public void Index_SortsByLastNameAscending_ByDefault()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Default sort is by LastName ascending: Adams, Brown, Doe
            Assert.Equal("Adams", model[0].LastName);
        }

        [Fact]
        public void Index_SortsByLastNameDescending_WhenNameDescSort()
        {
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal("Doe", model[0].LastName);
        }

        [Fact]
        public void Index_SortsByDateAscending()
        {
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Earliest date first
            Assert.Equal("Adams", model[0].LastName); // 2019
        }

        [Fact]
        public void Index_SortsByDateDescending()
        {
            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            // Latest date first
            Assert.Equal("Brown", model[0].LastName); // 2021
        }

        [Fact]
        public void Index_FiltersStudentsBySearchString()
        {
            var result = _controller.Index(null, null, "Doe", null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Doe", model[0].LastName);
        }

        [Fact]
        public void Index_FiltersStudentsByFirstName()
        {
            var result = _controller.Index(null, null, "Alice", null) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Alice", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SearchStringResetsPage()
        {
            var result = _controller.Index(null, null, "Doe", null) as ViewResult;

            // When searchString is provided, page resets to 1
            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_UsesCurrentFilterWhenSearchStringIsNull()
        {
            var result = _controller.Index(null, "Adams", null, 1) as ViewResult;

            var model = result!.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
        }

        [Fact]
        public void Details_ReturnsNotFound_WhenIdIsNull()
        {
            var result = _controller.Details(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Details_ReturnsViewResult_WhenStudentExists()
        {
            var result = _controller.Details(10) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal("Doe", model.LastName);
        }

        [Fact]
        public void Create_Get_ReturnsViewResult_WithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                LastName = "NewStudent",
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_ValidStudent_SavesInDatabase()
        {
            var student = new Student
            {
                LastName = "SaveTest",
                FirstMidName = "DB",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            _controller.Create(student);

            Assert.Contains(_context.Students, s => s.LastName == "SaveTest");
        }

        [Fact]
        public void Create_Post_InvalidEnrollmentDate_ReturnsView()
        {
            var student = new Student
            {
                LastName = "Bad",
                FirstMidName = "Date",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_DateBeforeSqlMin_ReturnsView()
        {
            var student = new Student
            {
                LastName = "Old",
                FirstMidName = "History",
                EnrollmentDate = new DateTime(1000, 1, 1)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Edit_Get_ReturnsNotFound_WhenIdIsNull()
        {
            var result = _controller.Edit(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Edit_Get_ReturnsNotFound_WhenStudentDoesNotExist()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ReturnsViewResult_WhenStudentExists()
        {
            var result = _controller.Edit(10) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal("Doe", model.LastName);
        }

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = _context.Students.AsNoTracking().First(s => s.ID == 10);
            student.LastName = "UpdatedDoe";

            var result = _controller.Edit(student) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidEnrollmentDate_ReturnsView()
        {
            var student = new Student
            {
                ID = 10,
                LastName = "Doe",
                FirstMidName = "Alice",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Edit(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Delete_Get_ReturnsBadRequest_WhenIdIsNull()
        {
            var result = _controller.Delete(null);

            Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, ((StatusCodeResult)result).StatusCode);
        }

        [Fact]
        public void Delete_Get_ReturnsNotFound_WhenStudentDoesNotExist()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ReturnsViewResult_WhenStudentExists()
        {
            var result = _controller.Delete(10) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as Student;
            Assert.NotNull(model);
            Assert.Equal("Doe", model.LastName);
        }

        [Fact]
        public void DeleteConfirmed_RemovesStudentAndRedirects()
        {
            var result = _controller.DeleteConfirmed(10) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Students.Find(10));
        }
    }
}

