[Fact]
public void Edit_Post_ValidStudent_RedirectsToIndex()
{
    // Use a tracked entity to avoid EF InMemory tracking issues
    var student = _context.Students.First(s => s.ID == 10);
    student.LastName = "UpdatedDoe";
    // Detach so the controller can re-attach
    _context.Entry(student).State = EntityState.Detached;

    var result = _controller.Edit(student: student) as RedirectToActionResult;

    Assert.NotNull(result);
    Assert.Equal("Index", result.ActionName);
}

