[Fact]
public void Index_WithCourseId_PopulatesEnrollments()
{
    // Use a fresh context with minimal data to avoid Single() issues with InMemory duplicates
    var ctx = TestDbContextFactory.Create();
    var instructor = new Instructor
    {
        ID = 100,
        LastName = "TestInst",
        FirstMidName = "A",
        HireDate = new DateTime(2020, 1, 1),
        CourseAssignments = new List<CourseAssignment>()
    };
    ctx.Instructors.Add(instructor);

    var dept = new Department { DepartmentID = 100, Name = "D", Budget = 1000, StartDate = DateTime.Now };
    ctx.Departments.Add(dept);

    var course = new Course
    {
        CourseID = 9001,
        Title = "TestCourse",
        Credits = 3,
        DepartmentID = 100,
        Department = dept,
        Enrollments = new List<Enrollment>(),
        CourseAssignments = new List<CourseAssignment>()
    };
    ctx.Courses.Add(course);

    var ca = new CourseAssignment { CourseID = 9001, InstructorID = 100 };
    ctx.CourseAssignments.Add(ca);
    instructor.CourseAssignments.Add(ca);
    course.CourseAssignments.Add(ca);

    var student = new Student
    {
        ID = 100,
        LastName = "S",
        FirstMidName = "T",
        EnrollmentDate = DateTime.Now,
        Enrollments = new List<Enrollment>()
    };
    ctx.Students.Add(student);

    var enrollment = new Enrollment { EnrollmentID = 100, CourseID = 9001, StudentID = 100, Grade = Grade.A, Course = course, Student = student };
    ctx.Enrollments.Add(enrollment);
    course.Enrollments.Add(enrollment);
    ctx.SaveChanges();

    using var controller = new InstructorsController(ctx);
    var result = controller.Index(100, 9001) as ViewResult;

    var model = result!.Model as InstructorIndexData;
    Assert.NotNull(model);
    Assert.NotNull(model.Enrollments);
    Assert.True(model.Enrollments.Any());
    ctx.Dispose();
}

